export const flwspScreenPx = /* @__PURE__ */ screenFn(B, DpQualifier.WIDTH, KIND_SP, true);

// ── Builder (Android `DimenFill` / `FillSp`). ───────────────────────────
/** Custom-dimension builder for the fill strategy. */
export class DimenFill extends DimenBuilder {
  get flsdp(): number { return this.sdp; }
  get flsdpPx(): number { return this.sdpPx; }
  get flssp(): number { return this.ssp; }
  get flsspPx(): number { return this.sspPx; }
  get flsem(): number { return this.sem; }
  get flsemPx(): number { return this.semPx; }
  get flhdp(): number { return this.hdp; }
  get flhdpPx(): number { return this.hdpPx; }
  get flhsp(): number { return this.hsp; }
  get flhspPx(): number { return this.hspPx; }
  get flhem(): number { return this.hem; }
  get flhemPx(): number { return this.hemPx; }
  get flwdp(): number { return this.wdp; }
  get flwdpPx(): number { return this.wdpPx; }
  get flwsp(): number { return this.wsp; }
  get flwspPx(): number { return this.wspPx; }
  get flwem(): number { return this.wem; }
  get flwemPx(): number { return this.wemPx; }
}
/** Starts a builder: `fillDp(16).screen(UiModeType.TELEVISION, 40).flsdp`. */
export const fillDp = (value: number): DimenFill => new DimenFill(B, value);
/** Text builder (same class; read `.flssp` / `.flsem`). */
export const fillSp = (value: number): DimenFill => new DimenFill(B, value);
